import json,subprocess
query="""SELECT json_build_object('users',(SELECT count(*) FROM application.users),'admins',(SELECT count(*) FROM application.users WHERE role=0),'ownerFingerprint',(SELECT md5(string_agg(row_to_json(u)::text,',' ORDER BY id)) FROM application.users u),'notes',(SELECT count(*) FROM application.note),'teams',(SELECT count(*) FROM application.team),'pages',(SELECT count(*) FROM application.page),'nodes',(SELECT count(*) FROM application.node),'edges',(SELECT count(*) FROM application.edge),'consents',(SELECT count(*) FROM application.policy_consent),'unfinishedIndexJobs',(SELECT count(*) FROM ai.index_job WHERE status IN ('RUNNING','PENDING','RETRY_WAIT')),'prepared',(SELECT count(*) FROM pg_prepared_xacts));"""
r=subprocess.run(['docker','exec','trader-integrated547-db','psql','-XqAt','-v','ON_ERROR_STOP=1','-U','postgres','-d','trader_integrated','-c',query],capture_output=True,text=True)
assert r.returncode==0,'BASELINE_FAILED';x=json.loads(r.stdout);assert x['users']==x['admins']==1 and x['prepared']==0,'OWNER_BASELINE_REVIEW';print(json.dumps(x))
